using System;
using System.Diagnostics;
using System.Threading;

// PROGRAM: Mengamati ThreadPool vs Manual Dedicated Thread
Console.WriteLine($"=== METRIK THREAD SISTEM ===");
Console.WriteLine($"Hardware Cores : {Environment.ProcessorCount}");

ThreadPool.GetAvailableThreads(out int workerThreads, out int completionPortThreads);
Console.WriteLine($"ThreadPool Worker Threads Tersedia: {workerThreads}");

// Menjalankan tugas ringan via ThreadPool (Efisien, tanpa alokasi thread OS baru)
var sw = Stopwatch.StartNew();
ThreadPool.QueueUserWorkItem(_ => {
    Console.WriteLine($"[WORKER POOL] Thread ID: {Environment.CurrentManagedThreadId} | Waktu Eksekusi: {sw.ElapsedMilliseconds} ms");
});

Thread.Sleep(50); // Menunggu sejenak agar threadpool selesai dieksekusi

