using System;

public class ThreadMemoryCalculator
{
    public static long CalculateThreadStackMemoryMb(int activeThreadCount, int stackSizeKb = 1024)
    {
        if (activeThreadCount <= 0 || stackSizeKb <= 0) return 0;

        long totalKb = (long)activeThreadCount * stackSizeKb;
        return totalKb / 1024;
    }

    public static void Main()
    {
        Console.WriteLine($"1000 Thread: {CalculateThreadStackMemoryMb(1000)} MB");
        Console.WriteLine($"5000 Thread: {CalculateThreadStackMemoryMb(5000)} MB");
    }
}
